// ====== DATA STORE ======
        let allocations = JSON.parse(localStorage.getItem('ngcdf_allocations') || '[]');

        // ====== TAB NAVIGATION ======
        document.querySelectorAll('.nav-tab').forEach(tab => {
            tab.addEventListener('click', () => {
                document.querySelectorAll('.nav-tab').forEach(t => t.classList.remove('active'));
                document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
                tab.classList.add('active');
                document.getElementById('tab-' + tab.dataset.tab).classList.add('active');
            });
        });

        // ====== FORM SUBMISSION ======
        document.getElementById('allocation-form').addEventListener('submit', function(e) {
            e.preventDefault();

            const amount = document.querySelector('input[name="bursary-amount"]:checked');
            if (!amount) {
                showToast('Amount Required', 'Please select a bursary amount.', 'error');
                return;
            }

            const application = {
                id: 'BUR-' + Date.now().toString(36).toUpperCase(),
                name: document.getElementById('student-name').value.trim(),
                studentId: document.getElementById('student-id').value.trim(),
                phone: document.getElementById('student-phone').value.trim(),
                institution: document.getElementById('student-institution').value.trim(),
                level: document.getElementById('student-level').value,
                year: document.getElementById('student-year').value,
                constituency: document.getElementById('student-constituency').value,
                ward: document.getElementById('student-ward').value.trim(),
                amount: parseInt(amount.value),
                remarks: document.getElementById('student-remarks').value.trim(),
                date: new Date().toISOString(),
                status: 'Pending'
            };

            // Check for duplicate
            if (allocations.some(a => a.studentId === application.studentId)) {
                showToast('Duplicate Application', 'An application with this ID already exists. Use "Check Status" to track it.', 'error');
                return;
            }

            allocations.push(application);
            saveData();
            updateBeneficiariesTable();

            this.reset();
            showToast('Application Submitted!', `Reference: ${application.id} — Save this for tracking.`, 'success');

            // Show reference number
            setTimeout(() => {
                alert(`✅ Application Submitted Successfully!\n\nYour Reference Number: ${application.id}\n\nPlease save this number to track your application status.`);
            }, 500);
        });

        // ====== CHECK STATUS ======
        function checkStatus() {
            const query = document.getElementById('status-search-input').value.trim().toLowerCase();
            const resultEl = document.getElementById('status-result');

            if (!query) {
                showToast('Enter ID', 'Please enter your Reference Number or National ID.', 'warning');
                return;
            }

            const found = allocations.find(a =>
                a.id.toLowerCase() === query ||
                a.studentId.toLowerCase() === query
            );

            if (!found) {
                resultEl.innerHTML = `
                    <div style="text-align:center;padding:30px;background:var(--accent-light);border-radius:var(--radius);border:1px solid #ffcdd2;">
                        <i class="fas fa-times-circle" style="font-size:2rem;color:var(--accent);margin-bottom:12px;"></i>
                        <h3 style="color:var(--accent);margin-bottom:8px;">Application Not Found</h3>
                        <p style="color:var(--text-secondary);font-size:0.88rem;">No application found matching "<strong>${query}</strong>". Please check your reference number and try again.</p>
                    </div>
                `;
                return;
            }

            const d = new Date(found.date);
            const statusColors = { 'Pending': 'badge-pending', 'Approved': 'badge-success', 'Disbursed': 'badge-info', 'Rejected': 'badge-danger' };

            resultEl.innerHTML = `
                <div class="card" style="margin:0;border:2px solid var(--primary);">
                    <div class="card-header" style="background:var(--primary-light);">
                        <h2 style="color:var(--primary);"><i class="fas fa-check-circle"></i> Application Found</h2>
                        <span class="badge ${statusColors[found.status] || 'badge-warning'}">${found.status}</span>
                    </div>
                    <div class="card-body">
                        <div class="detail-row"><span class="detail-label">Reference No.</span><span class="detail-value">${found.id}</span></div>
                        <div class="detail-row"><span class="detail-label">Applicant Name</span><span class="detail-value">${found.name}</span></div>
                        <div class="detail-row"><span class="detail-label">ID / Adm No.</span><span class="detail-value">${found.studentId}</span></div>
                        <div class="detail-row"><span class="detail-label">Institution</span><span class="detail-value">${found.institution}</span></div>
                        <div class="detail-row"><span class="detail-label">Level</span><span class="detail-value">${found.level}</span></div>
                        <div class="detail-row"><span class="detail-label">Year of Study</span><span class="detail-value">${found.year || 'N/A'}</span></div>
                        <div class="detail-row"><span class="detail-label">Constituency</span><span class="detail-value">${found.constituency}</span></div>
                        <div class="detail-row"><span class="detail-label">Requested Amount</span><span class="detail-value amount-badge">KES ${found.amount.toLocaleString()}</span></div>
                        <div class="detail-row"><span class="detail-label">Date Applied</span><span class="detail-value">${d.toLocaleDateString('en-KE', { day:'2-digit', month:'long', year:'numeric' })}</span></div>
                        <div class="detail-row"><span class="detail-label">Status</span><span class="detail-value"><span class="badge ${statusColors[found.status] || 'badge-warning'}"><i class="fas fa-clock"></i> ${found.status}</span></span></div>
                    </div>
                </div>
            `;
        }

        // Allow Enter key on status search
        document.getElementById('status-search-input').addEventListener('keypress', function(e) {
            if (e.key === 'Enter') checkStatus();
        });

        // ====== BENEFICIARIES TABLE ======
        function updateBeneficiariesTable() {
            const tbody = document.getElementById('students-table-body');
            const emptyState = document.getElementById('students-empty');
            const searchVal = (document.getElementById('search-students').value || '').toLowerCase();
            const filterLevel = document.getElementById('filter-level').value;

            let filtered = allocations.filter(a => {
                const matchSearch = a.name.toLowerCase().includes(searchVal) || a.studentId.toLowerCase().includes(searchVal) || a.id.toLowerCase().includes(searchVal);
                const matchLevel = !filterLevel || a.level === filterLevel;
                return matchSearch && matchLevel;
            });

            if (filtered.length === 0) {
                tbody.innerHTML = '';
                emptyState.style.display = 'block';
                return;
            }

            emptyState.style.display = 'none';
            const statusColors = { 'Pending': 'badge-pending', 'Approved': 'badge-success', 'Disbursed': 'badge-info', 'Rejected': 'badge-danger' };

            tbody.innerHTML = filtered.map((a, i) => `
                <tr>
                    <td>${i + 1}</td>
                    <td><strong>${a.name}</strong></td>
                    <td style="font-family:monospace;font-size:0.82rem;">${a.id}</td>
                    <td>${a.institution}</td>
                    <td><span class="badge badge-info">${a.level}</span></td>
                    <td class="amount-badge">KES ${a.amount.toLocaleString()}</td>
                    <td><span class="badge ${statusColors[a.status] || 'badge-warning'}"><i class="fas fa-clock"></i> ${a.status}</span></td>
                    <td>
                        <button class="btn btn-outline btn-sm" onclick="viewStudent('${a.id}')" title="View Details">
                            <i class="fas fa-eye"></i>
                        </button>
                    </td>
                </tr>
            `).join('');
        }

        // ====== VIEW STUDENT MODAL ======
        function viewStudent(id) {
            const a = allocations.find(x => x.id === id);
            if (!a) return;
            const d = new Date(a.date);
            const statusColors = { 'Pending': 'badge-pending', 'Approved': 'badge-success', 'Disbursed': 'badge-info', 'Rejected': 'badge-danger' };
            document.getElementById('modal-body').innerHTML = `
                <div class="detail-row"><span class="detail-label">Reference No.</span><span class="detail-value" style="font-family:monospace;">${a.id}</span></div>
                <div class="detail-row"><span class="detail-label">Full Name</span><span class="detail-value">${a.name}</span></div>
                <div class="detail-row"><span class="detail-label">ID / Adm No.</span><span class="detail-value">${a.studentId}</span></div>
                <div class="detail-row"><span class="detail-label">Phone</span><span class="detail-value">${a.phone || 'N/A'}</span></div>
                <div class="detail-row"><span class="detail-label">Institution</span><span class="detail-value">${a.institution}</span></div>
                <div class="detail-row"><span class="detail-label">Level</span><span class="detail-value">${a.level}</span></div>
                <div class="detail-row"><span class="detail-label">Year of Study</span><span class="detail-value">${a.year || 'N/A'}</span></div>
                <div class="detail-row"><span class="detail-label">Constituency</span><span class="detail-value">${a.constituency}</span></div>
                <div class="detail-row"><span class="detail-label">Ward</span><span class="detail-value">${a.ward || 'N/A'}</span></div>
                <div class="detail-row"><span class="detail-label">Requested Amount</span><span class="detail-value amount-badge">KES ${a.amount.toLocaleString()}</span></div>
                <div class="detail-row"><span class="detail-label">Date Applied</span><span class="detail-value">${d.toLocaleDateString('en-KE', { day: '2-digit', month: 'long', year: 'numeric' })}</span></div>
                <div class="detail-row"><span class="detail-label">Status</span><span class="detail-value"><span class="badge ${statusColors[a.status] || 'badge-warning'}">${a.status}</span></span></div>
                <div class="detail-row"><span class="detail-label">Remarks</span><span class="detail-value">${a.remarks || 'None'}</span></div>
            `;
            document.getElementById('student-modal').classList.add('show');
        }

        function closeModal() {
            document.getElementById('student-modal').classList.remove('show');
        }

        function printStudent() {
            const content = document.getElementById('modal-body').innerHTML;
            const win = window.open('', '_blank');
            win.document.write(`
                <html><head><title>NG-CDF Bursary - Application Details</title>
                <style>
                    body { font-family: Arial, sans-serif; padding: 30px; }
                    h1 { color: #006B3F; font-size: 1.3rem; border-bottom: 2px solid #006B3F; padding-bottom: 10px; }
                    .detail-row { display: flex; justify-content: space-between; padding: 8px 0; border-bottom: 1px solid #eee; }
                    .detail-label { color: #666; font-size: 0.85rem; }
                    .detail-value { font-weight: 600; font-size: 0.9rem; }
                    .amount-badge { color: #006B3F; }
                    .badge { padding: 2px 8px; border-radius: 10px; font-size: 0.8rem; }
                </style></head><body>
                <h1>🇰🇪 NG-CDF Bursary Application Receipt</h1>
                ${content}
                <p style="margin-top:40px;font-size:0.8rem;color:#999;">Printed on ${new Date().toLocaleString()}</p>
                </body></html>
            `);
            win.document.close();
            win.print();
        }

        // ====== SEARCH & FILTER LISTENERS ======
        document.getElementById('search-students').addEventListener('input', updateBeneficiariesTable);
        document.getElementById('filter-level').addEventListener('change', updateBeneficiariesTable);

        // ====== TOAST ======
        function showToast(title, message, type = 'success') {
            const container = document.getElementById('toast-container');
            const icons = { success: 'fas fa-check-circle', error: 'fas fa-times-circle', warning: 'fas fa-exclamation-triangle' };
            const toast = document.createElement('div');
            toast.className = `toast ${type}`;
            toast.innerHTML = `
                <i class="${icons[type]} toast-icon ${type}"></i>
                <div class="toast-text">
                    <strong>${title}</strong>
                    <span>${message}</span>
                </div>
            `;
            container.appendChild(toast);
            setTimeout(() => {
                toast.style.opacity = '0';
                toast.style.transform = 'translateX(100%)';
                toast.style.transition = 'all 0.3s';
                setTimeout(() => toast.remove(), 300);
            }, 4000);
        }

        // ====== PERSISTENCE ======
        function saveData() {
            localStorage.setItem('ngcdf_allocations', JSON.stringify(allocations));
        }

        // ====== CLOSE MODAL ON OVERLAY ======
        document.getElementById('student-modal').addEventListener('click', function(e) {
            if (e.target === this) closeModal();
        });

        // ====== INIT ======
        updateBeneficiariesTable();